//! Rust translation of the C library in `c_src/`.
//!
//! Public ABI (matches `nm -D` of the C shared object exactly):
//!   * `read_side_info`
//!
//! The translation is intentionally literal: evaluation order, integer widths,
//! truncating casts, the order of validation/error checks and even the quirks of
//! the original code are reproduced rather than "fixed".

#![allow(non_camel_case_types)]

use core::ffi::c_int;

/// `typedef struct { const uint8_t *buf; int pos, limit; } bs_t;`
/// (size 16, align 8 — verified against the C compiler.)
#[repr(C)]
pub struct bs_t {
    pub buf: *const u8,
    pub pos: c_int,
    pub limit: c_int,
}

/// `L3_gr_info_t` — size 32, align 8, field offsets verified against the C
/// compiler (sfbtab 0, part_23_length 8, big_values 10, scalefac_compress 12,
/// global_gain 14, block_type 15, mixed_block_flag 16, n_long_sfb 17,
/// n_short_sfb 18, table_select 19, region_count 22, subblock_gain 25,
/// preflag 28, scalefac_scale 29, count1_table 30, scfsi 31).
#[repr(C)]
pub struct L3_gr_info_t {
    pub sfbtab: *const u8,
    pub part_23_length: u16,
    pub big_values: u16,
    pub scalefac_compress: u16,
    pub global_gain: u8,
    pub block_type: u8,
    pub mixed_block_flag: u8,
    pub n_long_sfb: u8,
    pub n_short_sfb: u8,
    pub table_select: [u8; 3],
    pub region_count: [u8; 3],
    pub subblock_gain: [u8; 3],
    pub preflag: u8,
    pub scalefac_scale: u8,
    pub count1_table: u8,
    pub scfsi: u8,
}

// ---------------------------------------------------------------------------
// Scalefactor band tables.
//
// In C these are three function-local `static const uint8_t` arrays:
//   g_scf_long[8][23], g_scf_short[8][40], g_scf_mixed[8][40]
//
// `sr_idx` can reach 8 here (an invalid sample-rate index of 3 combined with
// MPEG1 gives 9, minus 1 => 8), so `g_scf_*[sr_idx]` may address one row PAST
// the end of a table. Rows 0..=7 -- every in-bounds case -- are what matters
// and they are byte-identical to the C tables below. Row 8 is out of bounds in
// C, where the pointer simply aliases whatever the linker happened to place
// next; that is undefined behaviour and is genuinely toolchain-dependent (gcc
// -O2/-O3 emits the order mixed, short, long, while gcc -O0 and clang emit
// long, short, mixed with padding), so no single stable C behaviour exists.
//
// We store all three tables in one contiguous blob reproducing the layout the
// optimized/CMake-Release C build emits into `.rodata`, verified byte-for-byte
// against `objdump -s -j .rodata` of the C shared object:
//
//   offset   0..320  g_scf_mixed (8 rows x 40)
//   offset 320..640  g_scf_short (8 rows x 40)
//   offset 640..824  g_scf_long  (8 rows x 23)
//
// So g_scf_mixed[8] aliases g_scf_short[0] and g_scf_short[8] aliases
// g_scf_long[0], exactly as in that C build. A zero pad follows so the
// g_scf_long[8] case stays inside our own allocation rather than being UB in
// Rust. (Rows written shorter than their declared length are zero-filled,
// which is what C does.)
// ---------------------------------------------------------------------------

const OFF_MIXED: usize = 0;
const OFF_SHORT: usize = 320;
const OFF_LONG: usize = 640;

